import React, { useState } from "react";
import { Link, useLocation } from "react-router-dom";
import { createPortal } from "react-dom";
import "./Navbar.css";
import logo from "../images/logo.png";

const isMay = new Date().getMonth() === 3 || new Date().getMonth() === 4;
const HEART_COUNT = 14;

/**
 * 공유 네비게이션 바
 * @param {function} [onPlansClick] - Plans 링크 클릭 시 추가 동작 (PlansPage 상태 리셋 등)
 */
export default function Navbar({ onPlansClick }) {
  const { pathname } = useLocation();
  const [open, setOpen] = useState(false);
  const [goldenOn, setGoldenOn] = useState(false);
  const [showHearts, setShowHearts] = useState(false);

  const toggleGolden = () => {
    const next = !goldenOn;
    setGoldenOn(next);
    document.body.classList.toggle("golden-mode", next);
    if (next) {
      setShowHearts(true);
      setTimeout(() => setShowHearts(false), 4000);
    }
  };

  const cls = (path) => {
    const active =
      path === "/"
        ? pathname === "/"
        : path === "/members"
        ? pathname.startsWith("/members")
        : pathname === path;
    return `navLink${active ? " active" : ""}`;
  };

  const close = () => setOpen(false);

  return (
    <header className="navbar">
      {showHearts && createPortal(
        <div className="coralHearts" aria-hidden="true">
          {Array.from({ length: HEART_COUNT }).map((_, i) => (
            <span key={i} className={`heart heart-${i + 1}`}>🩷</span>
          ))}
        </div>,
        document.body
      )}

      <Link to="/" className="navBrand" onClick={close}>
        <img src={logo} alt="KorA Valley" className="navLogo" />
      </Link>

      {/* 데스크탑 네비 */}
      <nav className="navLinks" aria-label="main navigation">
        <Link className={cls("/")} to="/">Main</Link>
        <Link className={cls("/members")} to="/members">Members</Link>
        <Link className={cls("/plans")} to="/plans" onClick={onPlansClick}>Plans</Link>
        <Link className={cls("/insights")} to="/insights">Insights</Link>
        <Link className={cls("/networking")} to="/networking">Networking</Link>
        {isMay && (
          <button
            className={`goldenToggleBtn${goldenOn ? " golden-on" : ""}`}
            onClick={toggleGolden}
            title={goldenOn ? "기본 테마로 돌아가기" : "골든 에디션 켜기"}
          >
            🩷
          </button>
        )}
      </nav>

      {/* 햄버거 버튼 (모바일) */}
      <button
        className={`navHamburger${open ? " open" : ""}`}
        onClick={() => setOpen((v) => !v)}
        aria-label={open ? "메뉴 닫기" : "메뉴 열기"}
        aria-expanded={open}
      >
        <span />
        <span />
        <span />
      </button>

      {/* 모바일 메뉴 */}
      {open && createPortal(
        <>
          <div className="navOverlay" onClick={close} aria-hidden="true" />
          <nav className="navMobile" aria-label="mobile navigation">
            <Link className={cls("/")} to="/" onClick={close}>Main</Link>
            <Link className={cls("/members")} to="/members" onClick={close}>Members</Link>
            <Link
              className={cls("/plans")}
              to="/plans"
              onClick={() => { onPlansClick?.(); close(); }}
            >Plans</Link>
            <Link className={cls("/insights")} to="/insights" onClick={close}>Insights</Link>
            <Link className={cls("/networking")} to="/networking" onClick={close}>Networking</Link>
            {isMay && (
              <button
                className={`goldenToggleBtn mobile${goldenOn ? " golden-on" : ""}`}
                onClick={() => { toggleGolden(); close(); }}
              >
                {goldenOn ? "🩷 코랄 에디션 끄기" : "🩷 코랄 에디션 켜기"}
              </button>
            )}
          </nav>
        </>,
        document.body
      )}
    </header>
  );
}
